new:
  recordedById: true,
} as const;

const ITEM_PAYMENT = { ...VISIT_PAYMENT, voidedAt: true, voidedById: true, voidReason: true } as const;

/**
 * The space's payment, its row locked (`FOR UPDATE`) in the caller's transaction, voided or not;
 * `null` when the space has none with this id.
 */
async lockIn(spaceId: number, id: number, tx: Tx): Promise<ItemPaymentRow | null> {
  const locked = await tx.$queryRaw<{ id: number }[]>`
    SELECT id FROM payments WHERE id = ${id} AND space_id = ${spaceId} FOR UPDATE`;
  if (locked.length === 0) return null;
  return tx.payment.findUniqueOrThrow({ where: { id }, select: ITEM_PAYMENT });
},

/** Voids the payment: its void's three columns, and nothing else (the change trigger's rule). */
void(
  id: number,
  { at, byId, reason }: { at: Date; byId: number; reason: string },
  tx: Tx,
): Promise<ItemPaymentRow> {
  return tx.payment.update({
    where: { id },
    data: { voidedAt: at, voidedById: byId, voidReason: reason },
    select: ITEM_PAYMENT,
  });
},

/** Inserts the payment; the insert trigger checks it against its item's due. */

old:
        ? { at: voidedAt.toISOString(), byId: voidedById, reason: voidReason }
        : null,
  };
}

new:
        ? { at: voidedAt.toISOString(), byId: voidedById, reason: voidReason }
        : null,
  };
}

/** A payment as the payments list shows it, with the names its item, customer and people have. */
export function toPaymentRow(
  row: ItemPaymentRow,
  names: {
    item: PaymentItem;
    customer: { id: number; name: string } | null;
    recordedBy: { id: number; name: string };
    voidedBy: { id: number; name: string } | null;
  },
): PaymentRow {
  const { voidedAt, voidReason } = row;
  return {
    id: row.id,
    amountAgorot: row.amountAgorot,
    method: row.method,
    note: row.note,
    receivedAt: row.receivedAt.toISOString(),
    item: names.item,
    customer: names.customer,
    recordedBy: names.recordedBy,
    voided:
      voidedAt && names.voidedBy && voidReason !== null
        ? { at: voidedAt.toISOString(), by: names.voidedBy, reason: voidReason }
        : null,
  };
}

